Here is the commit message:
watchdog: lenovo_se10_wdt: Convert comma to semicolon

Replace a comma between expression statements by a semicolon.

Fixes: 1f6602c8ed1e ("watchdog: lenovo_se10_wdt: Watchdog driver for Lenovo SE10 platform")
Signed-off-by: Chen Ni <nichen@iscas.ac.cn>
Reviewed-by: Guenter Roeck <linux@roeck-us.net>
Reviewed-by: Mark Pearson <mpearson-lenovo@squebb.ca>
Link: https://lore.kernel.org/r/20240716030725.400400-1-nichen@iscas.ac.cn
Signed-off-by: Guenter Roeck <linux@roeck-us.net>
Signed-off-by: Wim Van Sebroeck <wim@linux-watchdog.org>

Here is the root cause:
The bug was caused by the incorrect use of a comma instead of a semicolon in the assignment statements, which led to improper termination of the statements. This could result in unexpected behavior during the execution of the code, as the compiler may interpret the statements incorrectly, potentially causing runtime errors or incorrect functionality in the watchdog driver.

Here is the patch:

 static int se10_wdt_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct se10_wdt *priv;
 	unsigned int chip_id;
 	int ret;

 	if (!request_muxed_region(CFG_PORT, CFG_SIZE, DRVNAME))
 		return -EBUSY;

 	chip_id = get_chipID();
 	if (chip_id != 0x5632) {
 		release_region(CFG_PORT, CFG_SIZE);
 		return -ENODEV;
 	}

 	lpc_write(CFG_LDN, CFG_BRAM_LDN);
 	bram_base = (lpc_read(0x60) << 8) | lpc_read(0x61);
 	release_region(CFG_PORT, CFG_SIZE);

 	dev_info(dev, "Found Lenovo SE10 0x%x\n", chip_id);

 	priv = devm_kzalloc(dev, sizeof(*priv), GFP_KERNEL);
 	if (!priv)
 		return -ENOMEM;

 	watchdog_set_drvdata(&priv->wdd, priv);

 	priv->wdd.parent = dev;
-	priv->wdd.info = &wdt_info,
-	priv->wdd.ops = &se10_wdt_ops,
+	priv->wdd.info = &wdt_info;
+	priv->wdd.ops = &se10_wdt_ops;
 	priv->wdd.timeout = WATCHDOG_TIMEOUT; /* Set default timeout */
 	priv->wdd.min_timeout = MIN_TIMEOUT;
 	priv->wdd.max_timeout = MAX_TIMEOUT;

 	set_bram(CUS_WDT_CFG, WATCHDOG_TIMEOUT); /* Set time to default */

 	watchdog_init_timeout(&priv->wdd, timeout, dev);
 	watchdog_set_nowayout(&priv->wdd, nowayout);
 	watchdog_stop_on_reboot(&priv->wdd);
 	watchdog_stop_on_unregister(&priv->wdd);

 	ret = devm_watchdog_register_device(dev, &priv->wdd);

 	dev_dbg(&pdev->dev, "initialized. timeout=%d sec (nowayout=%d)\n",
 		priv->wdd.timeout, nowayout);

 	return ret;
 }



